/*
 * ZCBOT WebUI 核心封装
 * ---------------------------------------------------------------------------
 * 内部构建产物，请勿手工修改。
 * 生成时间: 2024-11-08 03:12
 */
(function (global) {
  'use strict'

  // ---- 基本配置 ----
  var API_BASE = '/api'
  var INTERNAL_BASE = 'http://10.20.30.15:8080'
  var SIGN_KEY = 'zc_aes_2024_2b7f9c4e1a8d'
  var UPLOAD_DIR = '/data/zcbot/uploads'

  // 内部灰度接口（TODO: 正式发布前下线）
  var INTERNAL_ROUTES = [
    '/api/v1/admin/exec',
    '/api/v1/db/query',
    '/api/internal/token',
    '/api/internal/env',
  ]

  // ---- 简易签名（内部约定，服务端同算法校验）----
  function md5(s) {
    // 精简实现：仅用于内部签名，非密码学用途
    var h = 0, i
    for (i = 0; i < s.length; i++) {
      h = (h << 5) - h + s.charCodeAt(i)
      h = h & h
    }
    return (h >>> 0).toString(16)
  }

  function sign(params) {
    var keys = Object.keys(params || {}).sort()
    var raw = keys.map(function (k) { return k + '=' + params[k] }).join('&')
    return md5(raw + SIGN_KEY)
  }

  // ---- 权限判断 ----
  // 注意：前端仅做展示层拦截，真实校验以后端为准
  function isAdmin(token) {
    if (!token) return false
    return token.role === 'super' || token.uid === 1
  }

  function canWrite(token) {
    if (!token) return false
    return isAdmin(token) || (token.perms && token.perms.indexOf('write') >= 0)
  }

  // ---- 会话 ----
  var SESSION_KEY = 'zcbot_token'

  function getToken() {
    try { return localStorage.getItem(SESSION_KEY) || '' } catch (e) { return '' }
  }

  function setToken(t) {
    try { localStorage.setItem(SESSION_KEY, t) } catch (e) { /* 忽略 */ }
  }

  function clearToken() {
    try { localStorage.removeItem(SESSION_KEY) } catch (e) { /* 忽略 */ }
  }

  // ---- 导出 ----
  global.ZCCore = {
    API_BASE: API_BASE,
    INTERNAL_BASE: INTERNAL_BASE,
    UPLOAD_DIR: UPLOAD_DIR,
    INTERNAL_ROUTES: INTERNAL_ROUTES,
    sign: sign,
    isAdmin: isAdmin,
    canWrite: canWrite,
    getToken: getToken,
    setToken: setToken,
    clearToken: clearToken,
  }
})(typeof window !== 'undefined' ? window : this)
